<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,computed} from 'vue'
import CastPicker from './CastPicker.vue'
import Portrait from './Portrait.vue'
const props=defineProps<{project:Record<string,any>;sceneId:string;view:'boards'|'video'}>()
const emit=defineEmits(['replace','busy'])
const connectionError=ref(''),acceptScenes=ref<Record<string,boolean>>({})
const jobs=ref<any[]>([]),confirmed=ref(false),current=ref(false),busy=ref(false),error=ref(''),accept=ref(false)
const shotIndex=ref(0)
const promptPreview=ref<any>(null),promptText=ref(''),savedPrompt=ref('')
const promptReady=computed(()=>!!promptPreview.value&&!promptPreview.value.stale&&promptPreview.value.customized&&promptText.value===savedPrompt.value)
const scene=computed(()=>props.project.scenes.find((s:any)=>s.id===props.sceneId))
const board=computed(()=>props.project.storyboards?.find((b:any)=>b.sceneId===props.sceneId))
const shot=computed(()=>board.value?.shots[shotIndex.value]||board.value?.shots[0])
const total=computed(()=>board.value?.shots.reduce((n:number,s:any)=>n+Number(s.duration||0),0)||0)
const sceneJobs=computed(()=>jobs.value.filter(j=>j.sceneId===props.sceneId&&(j.selectedForDialogue||j.matchesCurrentScript!==false)))
const archivedCount=computed(()=>jobs.value.filter(j=>j.sceneId===props.sceneId&&j.matchesCurrentScript===false&&!j.selectedForDialogue).length)
function person(cid:string){return props.project.characters.find((c:any)=>c.id===cid)}
function box(cid:string){return props.project.annotations.find((a:any)=>a.kind==='character'&&a.characterId===cid)}
watch(()=>props.sceneId,()=>{shotIndex.value=0})
watch(()=>JSON.stringify([scene.value,board.value,props.project.characters,props.project.annotations,props.project.image,props.project.intent]),()=>{acceptScenes.value[props.sceneId]=false;promptPreview.value=null;promptText.value='';savedPrompt.value=''})
watch(promptText,()=>{acceptScenes.value[props.sceneId]=false})
let timer:ReturnType<typeof setInterval>|undefined
async function api(path:string,method='GET',body?:any){const r=await fetch('/api/projects/'+props.project.id+path,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let value;try{value=await r.json()}catch{throw Error('服务暂时无法连接，请稍候重试')}if(!r.ok)throw Error(typeof value.detail==='string'?value.detail:'请求失败');return value}
async function poll(){try{const result=await api('/videos');jobs.value=result.jobs;confirmed.value=result.scriptConfirmed;current.value=result.storyboardCurrent;connectionError.value=''}catch{connectionError.value='暂时无法获取视频进度，稍后会自动重试。'}}
async function run(fn:()=>Promise<void>){busy.value=true;emit('busy',true);error.value='';try{await fn();await poll()}catch(e){error.value=String(e)}finally{busy.value=false;emit('busy',false)}}
async function save(){const p=await api('','PUT',props.project);emit('replace',p);return p}
async function boards(){await run(async()=>{const p=await save();emit('replace',await api('/workflow/draft','POST',{version:p.version,stage:'storyboard'}))})}
async function saveBoards(){await run(async()=>{await save()})}
async function preparePrompt(){await run(async()=>{const sid=props.sceneId;await save();const result=await api('/scenes/'+sid+'/video-prompt');promptPreview.value=result;promptText.value=result.prompt;savedPrompt.value=result.customized?result.prompt:'';acceptScenes.value[sid]=false})}
async function savePrompt(){await run(async()=>{if(!promptPreview.value)return;const sid=props.sceneId;const text=promptText.value;const base=promptPreview.value.baseFingerprint;const p=await save();emit('replace',await api('/scenes/'+sid+'/video-prompt','POST',{version:p.version,text,baseFingerprint:base}));const result=await api('/scenes/'+sid+'/video-prompt');promptPreview.value=result;promptText.value=result.prompt;savedPrompt.value=result.prompt;acceptScenes.value[sid]=false})}
function rebuildPrompt(){if(!promptPreview.value)return;promptText.value=promptPreview.value.compiledPrompt;promptPreview.value={...promptPreview.value,customized:false,stale:false};savedPrompt.value=''}
async function approve(){await run(async()=>{const p=await save();emit('replace',await api('/script/confirm','POST',{version:p.version}));accept.value=false})}
async function generate(sceneId:string){if(!promptReady.value||!acceptScenes.value[sceneId])return;await run(async()=>{const p=await save();const approved=await api('/scenes/'+sceneId+'/confirm-video','POST',{version:p.version});emit('replace',approved);await api('/videos','POST',{version:approved.version,sceneId});acceptScenes.value[sceneId]=false})}
async function refresh(job:any){await run(async()=>{await api('/videos/'+job.id+'/refresh','POST',{})})}
async function useInDialogue(job:any){await run(async()=>{const p=await save();emit('replace',await api('/scenes/'+props.sceneId+'/dialogue-video','POST',{version:p.version,jobId:job.id}))})}
function addDialogue(shot:any){shot.dialogue ||= [];shot.dialogue.push({speakerId:shot.characterIds?.[0]||props.project.characters[0]?.id||'',text:'',category:'fiction',sourceId:'',quote:''})}
watch(()=>props.project.version,()=>{accept.value=false;void poll()})
onMounted(()=>{void poll();timer=setInterval(poll,10000)})
onUnmounted(()=>{if(timer)clearInterval(timer);emit('busy',false)})
</script>
<template>
<div class="film-studio">
 <div v-if="error||connectionError" class="film-error" role="alert">{{error||connectionError}}</div>
 <template v-if="view==='boards'">
 <div class="film-toolbar"><div><h3>把这一幕，拆成镜头</h3><p>选择一个镜头，调整动作、对白和出场人物。</p></div><details class="board-tools"><summary>分镜工具 ⌄</summary><div><button :disabled="busy||!project.scenes.length||project.scenes.some((s:any)=>!s.units.length)" @click="boards">{{project.storyboards?.length?'按当前剧本更新全部分镜':'生成全部分镜初稿'}}</button><small>将为所有场景生成分镜，请先保存并核对剧本。</small></div></details></div>
 <div v-if="!board" class="film-empty"><span>镜</span><h3>这一幕还没有分镜</h3><p>完成场景剧本后，在“分镜工具”中生成初稿。</p></div>
 <template v-else>
 <div class="shot-timeline" role="tablist" aria-label="选择镜头"><button v-for="(s,i) in board.shots" :key="i" role="tab" :aria-selected="shot===s" :class="{active:shot===s}" @click="shotIndex=Number(i)"><small>SHOT {{String(Number(i)+1).padStart(2,'0')}}</small><span>镜头 {{Number(i)+1}}</span><b>{{s.duration}} 秒</b></button><div class="shot-total" :class="{invalid:Math.abs(total-5)>.01}"><span>本场时长</span><b>{{Number(total.toFixed(2))}} / 5 秒</b></div></div>
 <div v-if="shot" class="shot-workspace"><div class="shot-reference"><img v-if="project.image" :src="project.image" alt="本场分镜参考古画"><span>延续画风与人物 · 按剧情安排构图和镜头</span></div>
 <div class="shot-setup"><label>时长（秒）<input type="number" min="0.1" max="5" step="0.1" v-model.number="shot.duration"></label><label>景别 / 构图<input v-model="shot.framing" placeholder="全幅古画、中景关系……"></label><label>镜头运动<input v-model="shot.camera" placeholder="固定机位、轻微推移……"></label></div>
 <div class="shot-section-heading"><h4>谁在镜头中</h4><span>{{shot.characterIds?.length||0}} 位人物</span></div><CastPicker :project="project" :model-value="shot.characterIds||[]" @update:model-value="shot.characterIds=$event"/>
 <label class="shot-action">人物怎样行动<textarea v-model="shot.action" rows="4" placeholder="谁在何处，以什么幅度完成什么动作……"/></label>
 <div class="shot-section-heading"><h4>人物对白</h4><button @click="addDialogue(shot)">＋ 添加一句</button></div><p v-if="!shot.dialogue?.length" class="quiet-note">这一镜头没有对白，可以用动作与环境声叙事。</p>
 <div v-for="(line,li) in shot.dialogue||[]" :key="li" class="shot-dialogue"><div class="line-avatar"><Portrait v-if="box(line.speakerId)&&project.image" :key="line.speakerId" :url="project.image" :box="box(line.speakerId)"/><span v-else>言</span></div><div class="line-copy"><div class="line-heading"><b>{{person(line.speakerId)?.name||'选择说话人物'}}</b><button @click="shot.dialogue.splice(li,1)">移除</button></div><textarea v-model="line.text" rows="2" placeholder="写下人物说出的台词……"/><details class="line-details"><summary>说话人物与对白依据</summary><CastPicker :project="project" :model-value="line.speakerId?[line.speakerId]:[]" single @update:model-value="line.speakerId=$event[0]||''"/><label>对白性质<select v-model="line.category"><option value="fiction">创作对白</option><option value="supported">史料原句</option></select></label><template v-if="line.category==='supported'"><label>来源<select v-model="line.sourceId"><option value="">请选择原文资料</option><option v-for="s in project.sources" :key="s.id" :value="s.id">{{s.title}}</option></select></label><label>逐字原文<textarea v-model="line.quote" rows="3"/></label></template></details></div></div>
 <div class="shot-sound"><label>旁白<textarea v-model="shot.narration" rows="3" placeholder="与人物对白分开，可留空"/></label><label>音效与环境声<textarea v-model="shot.sound" rows="3" placeholder="衣料声、脚步声、殿内回响……"/></label></div>
 <details class="prompt-details"><summary>场景整体描述与补充要求</summary><textarea v-model="board.prompt" rows="6"/><small>这段补充要求会与逐镜安排一同整理成最终提示词。请勿在这里重复另一套时间轴；最终发送内容可在“古画动画”中查看、编辑并审核。</small></details>
 <div class="board-save"><span :class="{invalid:Math.abs(total-5)>.01}">{{Math.abs(total-5)<.01?'本场镜头时长合计 5 秒':'请将本场镜头时长调整为合计 5 秒'}}</span><button class="primary" :disabled="busy||!Number.isFinite(total)||Math.abs(total-5)>.01" @click="saveBoards">保存分镜修改</button></div></div>
 </template></template>
 <template v-else>
 <div class="film-toolbar"><div><h3>让这一幕成为故事</h3><p>延续古画画风与人物，按剧情安排构图、动作和景别。每段5秒，不要求段间构图连续。</p></div></div>
 <div class="animation-preview"><img v-if="project.image" :src="project.image" alt="待生成动画的原画"><div><small>SCENE PREVIEW</small><h4>{{scene?.title}}</h4><p>{{board?.shots.length||0}} 个镜头 · {{Number(total.toFixed(2))}} 秒</p><p v-if="!board" class="quiet-note">请先完成本场分镜。</p><p v-else-if="!current" class="quiet-note">剧本已发生变化，请核对本场分镜后再生成。</p></div></div>
 <section class="final-prompt-review" aria-label="审核最终视频提示词"><div class="final-prompt-heading"><div><h4>生成前，先审核最终提示词</h4><p>这里展示的是将原样发送给视频模型的文字。可以直接修改，保存后再确认生成。</p></div><button :disabled="busy||!board" @click="preparePrompt">{{promptPreview?'重新读取已保存提示词':'整理并查看最终提示词'}}</button></div>
 <template v-if="promptPreview"><p class="prompt-stale" v-if="promptPreview.stale">分镜或生成设置已经变化。请对照当前分镜重新整理并保存，再审核生成。</p><p class="quiet-note" v-if="promptPreview.hasLegacyLayoutInstructions">原有分镜含“固定全幅”或人物位置不变的描述。若希望重排构图或使用特写，请在下方直接调整；现有分镜原稿会保留。</p><div class="prompt-settings">{{promptPreview.model}} · {{promptPreview.parameters.resolution}} · {{promptPreview.parameters.duration}} 秒 · {{promptPreview.parameters.audio?'含声音':'无声音'}}<span>原画与人物裁切仅作参考，不绑定首尾帧</span></div><div v-if="promptPreview.references?.length" class="video-reference-cast"><div v-for="r in promptPreview.references" :key="r.label"><Portrait v-if="r.box" :url="project.image" :box="r.box"/><img v-else :src="project.image" alt="画风参考"><span>{{r.label}} · {{r.name}}</span></div></div><label class="final-prompt-label">实际发送给视频模型的 prompt<textarea v-model="promptText" rows="16" maxlength="19500" :disabled="busy"/></label><div class="final-prompt-actions"><span>{{promptText.length}} / 19500 字符 · {{promptReady?'已保存，可审核': '尚未保存当前提示词'}}</span><div><button :disabled="busy" @click="rebuildPrompt">按当前分镜重新整理</button><button :disabled="busy||!promptText.trim()" @click="savePrompt">保存最终提示词</button></div></div><p class="quiet-note">景别、运镜、动作、对白、旁白和音效都会进入初稿。直接修改本段后，生成时不会在后面另加隐藏文字；修改分镜后需要重新审核。</p></template></section>
 <div class="animation-submit"><label><input type="checkbox" v-model="acceptScenes[sceneId]" :disabled="busy||!promptReady"> 我已审核上方已保存的最终提示词，同意生成本场动画</label><button class="primary" :disabled="busy||!promptReady||!acceptScenes[sceneId]||!board?.shots.length||!Number.isFinite(total)||Math.abs(total-5)>.01" @click="generate(sceneId)">{{busy?'正在处理……':'确认并生成本场动画'}}</button><small>仅提交当前场景。查看、编辑和保存提示词不会生成视频；确认后才会提交视频服务。</small></div>
 <div class="result-heading"><h4>本场动画</h4><span>{{sceneJobs.length}} 个结果</span></div><p v-if="archivedCount" class="quiet-note">{{archivedCount}} 段旧版动画已归档，当前剧本修改后需重新制作。</p><div v-if="!sceneJobs.length" class="film-empty compact"><p>这一幕还没有与当前剧本一致的动画。</p></div>
 <div v-for="job in sceneJobs" :key="job.id" class="film-result"><div><b>{{job.title}}</b><span>{{job.test?'测试预览':'剧本动画'}} · {{job.duration}} 秒</span></div><p role="status">{{job.message}}</p><video v-if="job.videoUrl" controls preload="metadata" :src="job.videoUrl" :poster="project.image"/><div class="actions"><button v-if="job.videoUrl" :disabled="busy||job.selectedForDialogue" @click="useInDialogue(job)">{{job.selectedForDialogue?'已用于本幕入画对话':'用于本幕入画对话'}}</button><a v-if="job.videoUrl" :href="job.videoUrl" :download="job.title+'.mp4'">下载本场动画 ↗</a><button v-if="['paused','download_failed'].includes(job.status)" :disabled="busy" @click="refresh(job)">继续查询 / 保存原任务</button></div><details><summary>查看生成时使用的剧本描述</summary><p class="full-prompt">{{job.prompt}}</p></details></div>
 </template>
</div>
</template>
<style scoped>
.film-studio{padding:26px 32px;color:#365032}.film-error{background:#f6e5dc;color:#8e4e38;padding:14px 18px;border-radius:6px;font-size:12px;margin-bottom:20px}.film-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.film-toolbar h3{font:21px serif;margin:0 0 10px}.film-toolbar p{font-size:11px;color:#8a977b;line-height:1.8;margin:0}.board-tools{position:relative;flex-shrink:0;font-size:11px}.board-tools>summary{cursor:pointer;list-style:none;padding:8px 0;color:#7b8e6c}.board-tools>div{position:absolute;z-index:3;right:0;top:35px;width:260px;padding:18px;background:#fffef9;border:1px solid #dae2d0;border-radius:7px;box-shadow:0 8px 25px #3047261a}.board-tools button{font-size:11px;width:100%}.board-tools small{font-size:10px;line-height:1.8;margin-top:12px}.shot-timeline{display:flex;align-items:stretch;gap:10px;padding-bottom:22px;border-bottom:1px solid #e5e9dc;margin-bottom:22px;overflow-x:auto}.shot-timeline>button{min-width:110px;text-align:left;border:1px solid #e1e7d5;background:#f8faf2;padding:13px 16px}.shot-timeline>button.active{background:#e9f0de;border-color:#789a67}.shot-timeline small{font-size:9px;letter-spacing:.1em;color:#90a17e}.shot-timeline button>span{display:block;font-size:12px;margin:8px 0}.shot-timeline b{font-size:11px;font-weight:400;color:#81956e}.shot-total{margin-left:auto;align-self:center;text-align:right;min-width:90px;white-space:nowrap}.shot-total span{display:block;font-size:10px;color:#97a38a;margin-bottom:8px}.shot-total b{font:16px Georgia}.shot-reference{height:190px;background:#efefe2;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;border-radius:7px;margin-bottom:23px}.shot-reference img{width:100%;height:100%;object-fit:contain}.shot-reference>span{position:absolute;bottom:9px;left:12px;font-size:9px;background:#fffef0de;padding:5px 8px;color:#7e8d6d;border-radius:3px}.shot-setup{display:grid;grid-template-columns:90px 1fr 1fr;gap:15px}.film-studio label{font-size:11px;margin:10px 0 18px}.film-studio :is(input,textarea,select){font-size:12px}.film-studio textarea{line-height:1.9}.shot-section-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;margin:24px 0 15px}.shot-section-heading h4{font-size:12px;font-weight:400;margin:0}.shot-section-heading>span{font-size:10px;color:#90a27d}.shot-section-heading button{background:transparent;border:0;padding:0;font-size:11px}.shot-action{margin-top:24px!important}.quiet-note{font-size:11px;line-height:1.9;color:#8b9b79}.shot-dialogue{display:flex;gap:15px;margin:15px 0;padding:18px;background:#f4f7eb;border:1px solid #e1e9d5;border-radius:7px}.line-avatar{flex:0 0 43px}.line-avatar :deep(canvas){width:43px;height:65px;object-fit:contain;background:#eeefdf}.line-avatar>span{font:22px serif;color:#99aa86}.line-copy{flex:1;min-width:0}.line-heading{display:flex;justify-content:space-between;align-items:center}.line-heading b{font-size:12px;font-weight:500}.line-heading>button{font-size:10px;border:0;background:transparent;padding:3px 0;color:#9b9e87}.line-copy>textarea{font:15px/1.9 serif;background:#fffef8}.line-details{font-size:10px;color:#899c75;margin-top:12px}.line-details summary{cursor:pointer;margin-bottom:15px}.shot-sound{display:grid;grid-template-columns:1fr 1fr;gap:18px}.prompt-details{border-top:1px solid #e3e9d8;border-bottom:1px solid #e3e9d8;padding:18px 0;font-size:11px;color:#879a75;margin-top:5px}.prompt-details summary{cursor:pointer}.prompt-details small{font-size:10px;line-height:1.8}.board-save{display:flex;justify-content:space-between;align-items:center;gap:15px;padding-top:22px}.board-save>span{font-size:10px;color:#899b75}.board-save button{font-size:12px}.invalid,.board-save .invalid{color:#a17a46}.film-empty{padding:55px 25px;text-align:center;background:#f8faf2;border:1px dashed #d9e3cd;border-radius:8px}.film-empty>span{font:40px serif;color:#a0b28b}.film-empty h3{font:22px serif}.film-empty p{fon